"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[20538],{28453:(e,t,a)=>{a.d(t,{R:()=>r,x:()=>i});var s=a(96540);const o={},n=s.createContext(o);function r(e){const t=s.useContext(n);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),s.createElement(n.Provider,{value:t},e.children)}},77328:(e,t,a)=>{a.r(t),a.d(t,{assets:()=>l,contentTitle:()=>i,default:()=>u,frontMatter:()=>r,metadata:()=>s,toc:()=>h});const s=JSON.parse('{"id":"qiangguo/maopoemflaws4","title":"","description":"After the first three posts came out, some people indignantly accused this young lady of nitpicking Mao Zedong\'s poetry on prosodic grounds. But Mao Zedong explicitly labeled his poems as seven-character regulated verse, and seven-character regulated verse must obey these prosodic rules -- otherwise it shouldn\'t be called regulated verse. Of course, those who dislike prosodic constraints can choose not to write regulated verse and write old-style verse instead. Li Bai and Han Yu, for example, very rarely wrote seven-character regulated verse, but when they did, they followed the rules completely. Only this way can one avoid false advertising. If writing \\"seven-character regulated verse\\" that isn\'t actually seven-character regulated verse is acceptable, then the leftists\' pursuit of some \\"ism\\" can equally be something other than that \\"ism.\\" If everything goes like this, then what are the leftists arguing about online?","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/maopoemflaws4.md","sourceDirName":"qiangguo","slug":"/qiangguo/maopoemflaws4","permalink":"/en/qiangguo/maopoemflaws4","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"maopoemflaws4","title":"","hide_table_of_contents":true},"sidebar":"qiangguoSidebar","previous":{"title":"\u5bf9\u6bdb\u6cfd\u4e1c\u8bd7\u8bcd\u521b\u4f5c\u4e2d\u7684\u7f3a\u9677\u7684\u5ba2\u89c2\u8bc4\u4ef7 \uff08\u4e09\uff09","permalink":"/en/qiangguo/maopoemflaws3"},"next":{"title":"\u5bf9\u6bdb\u6cfd\u4e1c\u8bd7\u8bcd\u521b\u4f5c\u4e2d\u7684\u7f3a\u9677\u7684\u5ba2\u89c2\u8bc4\u4ef7\uff08\u4e94\uff09","permalink":"/en/qiangguo/maopoemflaws5"}}');var o=a(74848),n=a(28453);const r={id:"maopoemflaws4",title:"",hide_table_of_contents:!0},i="An Objective Evaluation of the Flaws in Mao Zedong's Poetry (Part Four)",l={},h=[];function c(e){const t={h1:"h1",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"an-objective-evaluation-of-the-flaws-in-mao-zedongs-poetry-part-four",children:"An Objective Evaluation of the Flaws in Mao Zedong's Poetry (Part Four)"})}),"\n",(0,o.jsx)(t.p,{children:'After the first three posts came out, some people indignantly accused this young lady of nitpicking Mao Zedong\'s poetry on prosodic grounds. But Mao Zedong explicitly labeled his poems as seven-character regulated verse, and seven-character regulated verse must obey these prosodic rules -- otherwise it shouldn\'t be called regulated verse. Of course, those who dislike prosodic constraints can choose not to write regulated verse and write old-style verse instead. Li Bai and Han Yu, for example, very rarely wrote seven-character regulated verse, but when they did, they followed the rules completely. Only this way can one avoid false advertising. If writing "seven-character regulated verse" that isn\'t actually seven-character regulated verse is acceptable, then the leftists\' pursuit of some "ism" can equally be something other than that "ism." If everything goes like this, then what are the leftists arguing about online?'}),"\n",(0,o.jsx)(t.p,{children:"What the world fears most is seriousness, and no one in the world should be treated as special -- no matter who they are. For instance, in poetry, since you dare to label something as seven-character regulated verse, anyone has the right to first measure that poem against the standards of seven-character regulated verse. Good poetry must be perfect in both form and content. If the form doesn't even pass muster, what else is there to say? Or just don't call it seven-character regulated verse -- then write however you like, as long as you manage to string together eight lines totaling fifty-six characters. Under this rule, everyone is equal, and no one gets special treatment. The reason for saying the above is to emphasize that there must be an objective standard. Without an objective standard, everything is nonsense."}),"\n",(0,o.jsx)(t.p,{children:"Since Mao Zedong's shi poems are primarily labeled as seven-character regulated verse, let me offer an evaluation: formally, they have not yet achieved perfection. The tonal patterns are basically fine, but the rhyming has many problems. Since Mao Zedong attended a private school in his youth, mastering Pingshui rhymes was a most basic requirement. Therefore, using Pingshui rhymes to analyze his regulated verse is perfectly normal and not at all unfair. In terms of structure -- the introduction, development, turn, and conclusion -- some are poorly executed while others are passable. The problem of \"having couplets but no poem\" (individual lines are fine but the whole lacks cohesion) is quite serious. Overall, Mao Zedong's poems succeed purely through momentum, sometimes verging on coarseness. This is a common malady in the bold and unconstrained school -- even Su Shi occasionally succumbed to it -- so it is not surprising."})]})}function u(e={}){const{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}}}]);